function profile(
  defaultBase: number,
  baseByIndex: Record<number, number>,
  options: Partial<Omit<ProcessFamilyProfile, 'defaultBase' | 'baseByIndex'>> = {},
): ProcessFamilyProfile {
  return {
    defaultBase,
    baseByIndex,
    min: options.min ?? 1,
    max: options.max ?? Math.max(4, Math.ceil(defaultBase * 2.2)),
    spread: options.spread ?? 0.35,
    fixedRatio: options.fixedRatio ?? 0.25,
    complexity: options.complexity ?? 'medium',
    basis: options.basis ?? 'process duration refined by standard catalog code, process order and family duration quota',
  }
}

function family(input: Omit<DurationFamilyDefinition, 'sourceVersion'>): DurationFamilyDefinition {
  return input
}

