const STANDARD_CATALOG_PREFIXES_BY_DURATION_RULE = Object.fromEntries(
  FAMILY_DEFINITIONS.map((item) => [item.stableCode, item.standardCatalogCodePrefixes]),
) as Record<string, string[]>

const PROCESS_LEVEL_DURATION_EVIDENCE_KEYS = [
  'TY01_89_2016_DURATION_QUOTA',
  'BEIJING_2018_DURATION_QUOTA',
  'JIANGSU_2025_DURATION_QUOTA',
  'GB55032_2022_QUALITY_CONTROL',
  'V1472_STANDARD_LIBRARY',
]

function inferDurationCoverageMode(input: Pick<StandardWorkDurationSeedRule, 'stableCode' | 'standardCatalogCodePrefixes' | 'durationCoverageMode'>): NonNullable<StandardWorkDurationSeedRule['durationCoverageMode']> {
  if (input.durationCoverageMode) return input.durationCoverageMode
  const prefixes = input.standardCatalogCodePrefixes ?? STANDARD_CATALOG_PREFIXES_BY_DURATION_RULE[input.stableCode] ?? []
  if (prefixes.length === 0) return 'external_support'
  if (prefixes.length > 1) return 'family_fallback'
  return 'direct'
}

function resolveProjectTypeDurationFactors(definition: Pick<DurationFamilyDefinition, 'stableCode' | 'projectTypeDurationFactors'>) {
  return definition.projectTypeDurationFactors ?? PROJECT_TYPE_DURATION_FACTORS_BY_FAMILY[definition.stableCode]
}

function resolveStructureTypeDurationFactors(definition: Pick<DurationFamilyDefinition, 'stableCode' | 'standardCatalogCodePrefixes' | 'structureTypeDurationFactors'>) {
  if (definition.structureTypeDurationFactors) return definition.structureTypeDurationFactors

  const family = definition.stableCode
  const prefixes = definition.standardCatalogCodePrefixes ?? []
  const startsWith = (prefix: string) => prefixes.some((item) => item.startsWith(prefix))

  if (
    family.includes('ground')
    || family.includes('foundation')
    || family.includes('earthwork')
    || family.includes('pit')
    || family.includes('dewatering')
    || startsWith('01')
  ) return FOUNDATION_STRUCTURE_TYPE_FACTORS

  if (family.includes('basement')) return CIVIL_DEFENSE_STRUCTURE_TYPE_FACTORS

  if (
    family.includes('steel')
    || family.includes('large_span')
    || family.includes('timber')
    || startsWith('02-03')
    || startsWith('02-04')
    || startsWith('02-05')
    || startsWith('02-06')
  ) return STEEL_STRUCTURE_TYPE_FACTORS

  if (family.includes('pc_') || family.includes('prefab')) return PREFAB_STRUCTURE_TYPE_FACTORS

  if (family.includes('cast_in_place') || family.includes('concrete_curing')) return CAST_IN_PLACE_STRUCTURE_TYPE_FACTORS

  if (family.includes('masonry')) return MASONRY_STRUCTURE_TYPE_FACTORS

  if (
    family.includes('plumbing')
    || family.includes('hvac')
    || family.includes('electrical')
    || family.includes('intelligent')
    || family.includes('energy_')
    || family.includes('fire')
    || family.includes('mep')
  ) return MEP_STRUCTURE_TYPE_FACTORS

  if (family.includes('elevator')) return ELEVATOR_STRUCTURE_TYPE_FACTORS

  if (
    family.includes('finish')
    || family.includes('roof')
    || family.includes('waterproof')
    || family.includes('curtain')
    || family.includes('facade')
    || family.includes('door')
    || family.includes('window')
  ) return FINISH_STRUCTURE_TYPE_FACTORS

  return undefined
}

function inferRuleDurationContributionMode(input: Pick<StandardWorkDurationSeedRule, 'stableCode' | 'keywords' | 'durationCoverageMode' | 'durationContributionMode' | 'coverageRationale'>): DurationContributionMode {
  if (input.durationContributionMode) return input.durationContributionMode
  return inferDurationContributionMode({
    name: [
      input.stableCode,
      ...(input.keywords ?? []),
      input.coverageRationale,
      input.durationCoverageMode,
    ].filter(Boolean).join(' '),
    metadata: input as Record<string, unknown>,
  })
}

function hasSpecificStandardSourceForConfidence(input: Pick<StandardWorkDurationSeedRule, 'stableCode' | 'sourceStandard' | 'sourceClauseRef' | 'benchmarkBasis' | 'standardCatalogCodePrefixes'>) {
  const text = [
    input.stableCode,
    input.sourceStandard,
    input.sourceClauseRef,
    input.benchmarkBasis,
  ].join(' ').toLowerCase()

  return !text.includes('expert_estimate')
    && /ty01|gb\s*\d|gb\d/.test(text)
    && (input.standardCatalogCodePrefixes?.length ?? 0) > 0
    && !/before exact|family before exact|before project-specific/.test(text)
}

function inferDurationSeedConfidence(input: Pick<StandardWorkDurationSeedRule, 'stableCode' | 'sourceStandard' | 'sourceClauseRef' | 'benchmarkBasis' | 'confidence' | 'standardCatalogCodePrefixes'>): StandardWorkDurationSeedRule['confidence'] {
  if (input.confidence !== 'medium') return input.confidence

  const text = [
    input.stableCode,
    input.sourceStandard,
    input.sourceClauseRef,
    input.benchmarkBasis,
  ].join(' ').toLowerCase()

  if (
    text.includes('satellite')
    || text.includes('communication')
    || text.includes('intelligent')
    || text.includes('commissioning')
    || text.includes('trial operation')
  ) {
    return 'medium'
  }

  if (
    hasSpecificStandardSourceForConfidence(input)
    && (
      text.includes('ground')
      || text.includes('foundation')
      || text.includes('concrete')
      || text.includes('waterproof')
      || text.includes('membrane')
      || text.includes('roof')
    )
  ) {
    return 'high'
  }

  return input.confidence
}

function inferBaselineProductivitySourceType(input: Pick<StandardWorkDurationSeedRule, 'benchmarkBasis' | 'sourceStandard' | 'sourceClauseRef'>): BaselineProductivitySourceType {
  const text = [
    input.benchmarkBasis,
    input.sourceStandard,
    input.sourceClauseRef,
  ].join(' ').toLowerCase()

  if (text.includes('expertoverride=') || text.includes('expert_override=')) return 'expert_override'
  if (text.includes('domainexpert=') || text.includes('domain_profile=')) return 'expert_profile'
  if (text.includes('quota') || text.includes('ty01') || text.includes('beijing') || text.includes('jiangsu')) return 'quota'
  return 'derived_seed'
}

function slugQuotaPart(value: unknown, fallback: string) {
  const normalized = String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
  return normalized || fallback
}

function normalizeQuotaProductivityTrace(input: {
  stableCode?: string
  standardCatalogCodePrefixes?: string[]
  sourceStandard?: string
  sourceClauseRef?: string
  baselineProductivity: BaselineProductivity
}) {
  if (input.baselineProductivity.sourceType !== 'quota') return input.baselineProductivity

  const sourceRef = input.baselineProductivity.sourceRef ?? ''
  if (/^quota:[A-Z0-9-]+:chapter=[^:]+:table=[^:]+:item=[^:]+$/.test(sourceRef)) {
    const sourceDetail = input.baselineProductivity.sourceDetail
    const normalizedDetail = /chapter=.*table=.*item=/i.test(sourceDetail ?? '')
      ? sourceDetail
      : `${input.baselineProductivity.basis}; chapter=${slugQuotaPart(input.standardCatalogCodePrefixes?.[0], 'general')}; table=productivity_baseline; item=${slugQuotaPart(input.sourceClauseRef, slugQuotaPart(input.stableCode, 'standard_work'))}`
    return {
      ...input.baselineProductivity,
      sourceDetail: normalizedDetail,
    }
  }

  const standard = String(input.sourceStandard ?? sourceRef ?? 'TY01-89-2016').match(/[A-Z]{2}\d{2}-\d{2}-\d{4}|[A-Z]{2}\d{2}-\d{4}|[A-Z]+\s*\d{4}-\d{4}|TY\d{2}-\d{2}-\d{4}/i)?.[0]
    ?.replace(/\s+/g, '')
    .toUpperCase()
    ?? 'TY01-89-2016'
  const chapter = slugQuotaPart(input.standardCatalogCodePrefixes?.[0], 'general')
  const table = slugQuotaPart(input.baselineProductivity.unit, 'productivity') || 'productivity'
  const item = slugQuotaPart(input.sourceClauseRef ?? input.stableCode ?? input.baselineProductivity.basis, 'standard_work')
  const structuredRef = `quota:${standard}:chapter=${chapter}:table=${table}_productivity:item=${item}`
  const structuredDetail = [
    `chapter=${chapter}`,
    `table=${table}_productivity`,
    `item=${item}`,
    `basis=${input.baselineProductivity.basis}`,
    sourceRef ? `legacyRef=${sourceRef}` : '',
    input.baselineProductivity.sourceDetail ? `legacyDetail=${input.baselineProductivity.sourceDetail}` : '',
  ].filter(Boolean).join('; ')

  return {
    ...input.baselineProductivity,
    sourceRef: structuredRef,
    sourceDetail: /chapter=.*table=.*item=/i.test(input.baselineProductivity.sourceDetail ?? '')
      ? input.baselineProductivity.sourceDetail
      : structuredDetail,
  }
}

function normalizeProductivityBandTrace(
  input: Pick<StandardWorkDurationSeedRule, 'stableCode' | 'standardCatalogCodePrefixes' | 'sourceStandard' | 'sourceClauseRef' | 'productivityBands'>,
): StandardWorkDurationSeedRule['productivityBands'] {
  return input.productivityBands?.map((band) => ({
    ...band,
    baselineProductivity: normalizeQuotaProductivityTrace({
      stableCode: `${input.stableCode}:${band.conditionCode}`,
      standardCatalogCodePrefixes: input.standardCatalogCodePrefixes,
      sourceStandard: input.sourceStandard,
      sourceClauseRef: input.sourceClauseRef,
      baselineProductivity: {
        ...band.baselineProductivity,
        sourceType: band.baselineProductivity.sourceType ?? 'derived_seed',
        sourceRef: band.baselineProductivity.sourceRef
          ?? `${band.baselineProductivity.sourceType ?? 'derived_seed'}:${input.stableCode}:${band.conditionCode}`,
        sourceDetail: band.baselineProductivity.sourceDetail
          ?? [
            `owner=${input.stableCode}`,
            `condition=${band.conditionCode}`,
            `basis=${band.baselineProductivity.basis}`,
            `rationale=${band.rationale}`,
          ].join('; '),
      },
    }),
  }))
}

function normalizeBaselineProductivityTrace(input: Omit<StandardWorkDurationSeedRule, 'webVerified' | 'reviewNeeded'>): StandardWorkDurationSeedRule['baselineProductivity'] {
  if (!input.baselineProductivity) return undefined

  const sourceType = input.baselineProductivity.sourceType ?? inferBaselineProductivitySourceType(input)
  const sourceRef = input.baselineProductivity.sourceRef
    ?? input.sourceClauseRef
    ?? input.benchmarkBasis
    ?? input.sourceStandard
  const sourceDetail = input.baselineProductivity.sourceDetail
    ?? `${input.baselineProductivity.basis}; ${input.benchmarkBasis}`

  return normalizeQuotaProductivityTrace({
    stableCode: input.stableCode,
    standardCatalogCodePrefixes: input.standardCatalogCodePrefixes,
    sourceStandard: input.sourceStandard,
    sourceClauseRef: input.sourceClauseRef,
    baselineProductivity: {
      ...input.baselineProductivity,
      sourceType,
      sourceRef,
      sourceDetail,
    },
  })
}

function rule(input: Omit<StandardWorkDurationSeedRule, 'webVerified' | 'reviewNeeded'>): StandardWorkDurationSeedRule {
  const standardCatalogCodePrefixes = input.standardCatalogCodePrefixes ?? STANDARD_CATALOG_PREFIXES_BY_DURATION_RULE[input.stableCode] ?? []
  const durationCoverageMode = inferDurationCoverageMode({ ...input, standardCatalogCodePrefixes })
  const durationContributionMode = inferRuleDurationContributionMode({ ...input, durationCoverageMode })
  const baseDaysEligible = input.baseDaysEligible ?? durationContributionMode === 'duration_bearing'
  const baselineProductivity = normalizeBaselineProductivityTrace({ ...input, standardCatalogCodePrefixes })
  const productivityBands = normalizeProductivityBandTrace({ ...input, standardCatalogCodePrefixes })
  const confidence = inferDurationSeedConfidence({ ...input, standardCatalogCodePrefixes })
  return {
    ...input,
    standardCatalogCodePrefixes,
    durationCoverageMode,
    durationContributionMode,
    baseDaysEligible,
    baselineProductivity,
    productivityBands,
    confidence,
    coverageRationale: input.coverageRationale
      ?? (durationCoverageMode === 'external_support'
        ? 'Schedule-support duration seed outside the executable GB55032 process tree.'
        : 'Mapped to the v1.4.7.2 executable catalog by standard catalog code prefix.'),
    webVerified: true,
    reviewNeeded: false,
  }
}

function toBaseRule(definition: DurationFamilyDefinition): StandardWorkDurationSeedRule {
  const projectTypeDurationFactors = resolveProjectTypeDurationFactors(definition)
  const projectTypeCodes = definition.projectTypeCodes ?? Object.keys(projectTypeDurationFactors ?? {})
  const structureTypeDurationFactors = resolveStructureTypeDurationFactors(definition)
  const structureTypeCodes = definition.structureTypeCodes ?? Object.keys(structureTypeDurationFactors ?? {})
  return rule({
    stableCode: definition.stableCode,
    standardWorkCodes: [definition.stableCode],
    standardCatalogCodePrefixes: definition.standardCatalogCodePrefixes,
    durationCoverageMode: definition.durationCoverageMode,
    keywords: definition.keywords,
    projectTypeCodes,
    projectTypeDurationFactors,
    structureTypeCodes,
    structureTypeDurationFactors,
    applicableGranularity: 'both',
    defaultDaysP20: definition.defaultDaysP20,
    defaultDaysP50: definition.defaultDaysP50,
    defaultDaysP80: definition.defaultDaysP80,
    fixedDays: definition.fixedDays,
    variableDays: definition.variableDays,
    scaleBasis: definition.scaleBasis,
    conditionedDurationBands: definition.conditionedDurationBands,
    productivityBands: definition.productivityBands,
    conditionedProcessProfiles: definition.conditionedProcessProfiles,
    benchmarkBasis: definition.benchmarkBasis,
    sourceStandard: definition.sourceStandard,
    sourceVersion: 'system_initial_seed_2026',
    sourceClauseRef: definition.sourceClauseRef,
    evidenceSourceKeys: definition.evidenceSourceKeys,
    confidence: definition.confidence,
  })
}

