const DURATION_FAMILY_DEFINITION_BY_STABLE_CODE = new Map(
  FAMILY_DEFINITIONS.map((definition) => [definition.stableCode, definition]),
)

const DURATION_FAMILY_RULE_BY_STABLE_CODE = new Map(
  STANDARD_WORK_DURATION_BASE_SEED.map((rule) => [rule.stableCode, rule]),
)

function clampDuration(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, Math.round(value)))
}

function readProcessIndex(standardWorkCode: string) {
  const match = standardWorkCode.match(/-P(\d+)$/)
  return match ? Number(match[1]) : 1
}

function readMajorCatalogCode(standardWorkCode: string) {
  return standardWorkCode.split('-')[0] ?? ''
}

function numericCodeSignature(standardWorkCode: string) {
  return standardWorkCode
    .replace(/P/g, '-')
    .split('-')
    .map((part) => Number(part))
    .filter((part) => Number.isFinite(part))
    .reduce((sum, part, index) => sum + part * (index + 1), 0)
}

function findDurationFamilyDefinition(standardWorkCode: string) {
  const matches = FAMILY_DEFINITIONS
    .flatMap((definition) => definition.standardCatalogCodePrefixes.map((prefix) => ({ definition, prefix })))
    .filter(({ prefix }) => standardWorkCode === prefix || standardWorkCode.startsWith(`${prefix}-`))
    .sort((left, right) => right.prefix.length - left.prefix.length)
  return matches[0]?.definition ?? null
}

function findDurationFamilyRule(standardWorkCode: string) {
  const definition = findDurationFamilyDefinition(standardWorkCode)
  return definition
    ? STANDARD_WORK_DURATION_BASE_SEED.find((item) => item.stableCode === definition.stableCode) ?? null
    : null
}

function findDurationFamilyDefinitionByStableCode(stableCode: string | null | undefined) {
  const key = String(stableCode ?? '').trim()
  return key ? DURATION_FAMILY_DEFINITION_BY_STABLE_CODE.get(key) ?? null : null
}

function findDurationFamilyRuleByStableCode(stableCode: string | null | undefined) {
  const key = String(stableCode ?? '').trim()
  return key ? DURATION_FAMILY_RULE_BY_STABLE_CODE.get(key) ?? null : null
}

