function normalizeDurationMatchText(value: unknown) {
  return String(value ?? '').trim().toLowerCase()
}

function buildDomainProcessMatchText(node: ChinaTemplateCatalogNode, catalog: DomainWbsTemplateCatalog) {
  const metadata = node.metadata ?? {}
  return [
    node.stableCode,
    node.name,
    node.sourceClauseRef,
    node.sourceStandard,
    catalog.templateName,
    catalog.templateGroup,
    catalog.domainScope,
    metadata.applicableScope,
    metadata.nodeRole,
    metadata.planItemKind,
    metadata.processGranularity,
    ...(Array.isArray(metadata.planItemTags) ? metadata.planItemTags : []),
    ...(Array.isArray(catalog.triggerKeywords) ? catalog.triggerKeywords : []),
  ].map(normalizeDurationMatchText).filter(Boolean).join(' ')
}

function scoreDurationFamilyKeywords(definition: DurationFamilyDefinition, matchText: string) {
  return definition.keywords.reduce((score, keyword) => {
    const normalized = normalizeDurationMatchText(keyword)
    if (!normalized || !matchText.includes(normalized)) return score
    const isGeneric = DOMAIN_DURATION_GENERIC_KEYWORDS.has(keyword)
    return score + (isGeneric ? 2 : Math.min(24, Math.max(6, normalized.length * 2)))
  }, 0)
}

function findDurationFamilyDefinitionByDomainHints(matchText: string) {
  const hit = DOMAIN_PROCESS_DURATION_FAMILY_HINTS
    .map((hint, index) => ({
      hint,
      index,
      score: hint.terms.reduce((score, term) => (
        matchText.includes(normalizeDurationMatchText(term))
          ? score + Math.min(30, Math.max(10, term.length * 2))
          : score
      ), 0),
    }))
    .filter((item) => item.score > 0)
    .sort((left, right) => right.score - left.score || left.index - right.index)[0]

  return hit ? findDurationFamilyDefinitionByStableCode(hit.hint.familyStableCode) : null
}

function findDurationFamilyDefinitionByDomainKeywords(matchText: string) {
  const hit = FAMILY_DEFINITIONS
    .map((definition, index) => ({
      definition,
      index,
      score: scoreDurationFamilyKeywords(definition, matchText),
    }))
    .filter((item) => item.score > 0)
    .sort((left, right) => right.score - left.score || left.index - right.index)[0]

  return hit && hit.score >= 8 ? hit.definition : null
}

function findDomainFallbackDurationFamilyDefinition(catalog: DomainWbsTemplateCatalog) {
  return findDurationFamilyDefinitionByStableCode(
    DOMAIN_TEMPLATE_GROUP_DEFAULT_DURATION_FAMILY[catalog.templateGroup] ?? 'special_acceptance',
  )
}

function findDurationFamilyDefinitionForDomainProcess(node: ChinaTemplateCatalogNode, catalog: DomainWbsTemplateCatalog) {
  const matchText = buildDomainProcessMatchText(node, catalog)
  return findDurationFamilyDefinitionByStableCode(DOMAIN_PROCESS_DURATION_FAMILY_OVERRIDES[node.stableCode])
    ?? findDurationFamilyDefinitionByDomainHints(matchText)
    ?? findDurationFamilyDefinitionByDomainKeywords(matchText)
    ?? findDomainFallbackDurationFamilyDefinition(catalog)
}

function complexityFactor(complexity: ProcessFamilyProfile['complexity']) {
  if (complexity === 'high') return 1.08
  if (complexity === 'low') return 0.94
  return 1
}

function majorCatalogFactor(major: string) {
  if (major === '01') return 1.08
  if (major === '02') return 1.04
  if (major === '05' || major === '06' || major === '07' || major === '08' || major === '10') return 1.02
  if (major === '03' || major === '04') return 0.98
  return 1
}

function deterministicVariation(standardWorkCode: string) {
  const signature = numericCodeSignature(standardWorkCode)
  return 1 + ((signature % 9) - 4) * 0.035
}

