const exactProcessOverride = (
  p20: number,
  p50: number,
  p80: number,
  fixedRatio: number,
  defaultQuantityUnit: string,
  p50PerDay: number,
  productivityUnit: string,
  productivityBasis: string,
  reason: string,
): ProcessExpertDurationOverride => ({
  p20,
  p50,
  p80,
  fixedRatio,
  defaultQuantityUnit,
  baselineProductivity: { p50PerDay, unit: productivityUnit, basis: productivityBasis },
  reason,
})

const domainProcessExactOverride = (
  p50: number,
  defaultQuantityUnit: string,
  p50PerDay: number,
  productivityUnit: string,
  productivityBasis: string,
  reason: string,
  fixedRatio = 0.28,
): ProcessExpertDurationOverride => exactProcessOverride(
  Math.max(1, Math.round(p50 * 0.72)),
  p50,
  Math.max(p50 + 1, Math.round(p50 * 1.35)),
  fixedRatio,
  defaultQuantityUnit,
  p50PerDay,
  productivityUnit,
  productivityBasis,
  reason,
)

