const withMethodAndVariantBuckets = (
  override: ProcessExpertDurationOverride,
  options: {
    methodFactors?: Record<string, number>
    projectTypeCodes?: string[]
    projectTypeDurationFactors?: Record<string, number>
    elementVariantCodes?: string[]
    elementVariantDurationFactors?: Record<string, number>
  },
): ProcessExpertDurationOverride => ({
  ...override,
  durationContributionMode: override.durationContributionMode ?? 'duration_bearing',
  defaultDaysByMethod: options.methodFactors
    ? buildMethodBucketsFromFactors(override.p50, options.methodFactors, { enforceDistinctBuckets: true })
    : override.defaultDaysByMethod,
  projectTypeCodes: options.projectTypeCodes ?? override.projectTypeCodes,
  projectTypeDurationFactors: mergeDurationFactors(override.projectTypeDurationFactors, options.projectTypeDurationFactors),
  elementVariantCodes: options.elementVariantCodes ?? override.elementVariantCodes,
  elementVariantDurationFactors: mergeDurationFactors(override.elementVariantDurationFactors, options.elementVariantDurationFactors),
})

