type DomainFallbackSignalProfileKey = keyof typeof DOMAIN_FALLBACK_SIGNAL_EXACT_PROFILES

const domainFallbackSignalExact = (
  p50: number,
  profileKey: DomainFallbackSignalProfileKey,
  processLabel: string,
) => {
  const exactProfile = DOMAIN_FALLBACK_SIGNAL_EXACT_PROFILES[profileKey]
  return withMethodAndVariantBuckets(
    domainProcessExactOverride(
      p50,
      exactProfile.defaultQuantityUnit,
      exactProfile.p50PerDay,
      exactProfile.productivityUnit,
      exactProfile.productivityBasis,
      `${processLabel} exact domain-template duration override; replaces standard family fallback signal for a duration-bearing process`,
      exactProfile.fixedRatio,
    ),
    {
      methodFactors: exactProfile.methodFactors,
      projectTypeCodes: exactProfile.projectTypeCodes,
      projectTypeDurationFactors: exactProfile.projectTypeDurationFactors,
      elementVariantCodes: exactProfile.elementVariantCodes,
      elementVariantDurationFactors: exactProfile.elementVariantDurationFactors,
    },
  )
}

